/** Exact current-SDK build transition. All original inputs remain immutable;
 * every admitted generated byte becomes part of the subsequent full inventory.
 * Capture/derivation evidence only, never standalone packaging qualification. */
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {constants,closeSync,fstatSync,lstatSync,openSync,readSync,realpathSync,writeFileSync} from 'node:fs';
import {isAbsolute,join,relative,resolve} from 'node:path';
import {captureBuildInputs} from './build-input-inventory.mjs';

const hash=value=>createHash('sha256').update(value).digest('hex');
const APP='apps/eve',CACHE=APP+'/node_modules/.cache',EVE=CACHE+'/eve',MODULES=EVE+'/authored-modules';
const NITRO=APP+'/node_modules/.nitro',METADATA=NITRO+'/last-build.json';
const MAX_RECORD_BYTES=128*1024**2,MAX_DERIVED_BYTES=512*1024**2;
const under=(path,root)=>path===root||path.startsWith(root+'/');
const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
function validateRecord(record){
 assert(record?.format==='myapps.build-input-inventory.v1'&&record.status==='BUILD_INPUT_CAPTURE_ONLY_NOT_QUALIFIED','DERIVED_INPUT_RECORD_FORMAT');
 assert.deepEqual(Object.keys(record).sort(),['format','status','root','authoredFiles','installRoots','generatedBoundaries','entries','totalBytes','sha256'].sort(),'DERIVED_INPUT_RECORD_FIELDS');
 const {sha256,...payload}=record;assert.equal(hash(JSON.stringify(payload)),sha256,'DERIVED_INPUT_RECORD_CHANGED');
 assert(Array.isArray(record.entries)&&record.entries.length<=500000,'DERIVED_INPUT_RECORD_BOUND');
 for(const entry of record.entries)assert(typeof entry.path==='string'&&entry.path.length<=8192&&!isAbsolute(entry.path)
  &&!/[\\\0]/.test(entry.path)&&entry.path.split('/').every(part=>part&&part!=='.'&&part!=='..'),'DERIVED_INPUT_RECORD_PATH');
 const entries=new Map(record.entries.map(entry=>[entry.path,entry]));assert.equal(entries.size,record.entries.length,'DERIVED_INPUT_DUPLICATE_PATH');
 return entries;
}

export function assertEveDerivedInputsAbsent(record){
 const entries=validateRecord(record);
 assert(![...entries.keys()].some(path=>under(path,EVE)||under(path,NITRO)),'DERIVED_INPUT_PRESEEDED_NAMESPACE');
 if(entries.has(CACHE))assert.equal(entries.get(CACHE).type,'directory','DERIVED_INPUT_CACHE_PARENT');
 return {status:'EVE_DERIVED_NAMESPACES_ABSENT_NOT_QUALIFIED',beforeSha256:record.sha256};
}

/** Paths/types/modes/hashes only; no file contents or environment values. */
export function summarizeInputDifference(before,after){
 const a=validateRecord(before),b=validateRecord(after),sample=[];
 let added=0,removed=0,changed=0;
 for(const path of [...new Set([...a.keys(),...b.keys()])].sort()){
  const left=a.get(path),right=b.get(path);let kind;
  if(!left){added++;kind='added';}else if(!right){removed++;kind='removed';}else if(!same(left,right)){changed++;kind='changed';}
  if(kind&&sample.length<256){
   const safe=entry=>entry?Object.fromEntries(['type','mode','bytes','sha256'].filter(key=>entry[key]!==undefined).map(key=>[key,entry[key]])):null;
   sample.push({kind,path,before:safe(left),after:safe(right)});
  }
 }
 return {beforeSha256:before.sha256,afterSha256:after.sha256,added,removed,changed,sample,truncated:added+removed+changed>sample.length};
}

export function writePrivateInputInventory(path,record){
 validateRecord(record);const body=Buffer.from(JSON.stringify(record)+'\n');
 assert(body.length<=MAX_RECORD_BYTES,'DERIVED_INPUT_RECORD_TOO_LARGE');
 writeFileSync(path,body,{flag:'wx',mode:0o600});
 return {path,sha256:hash(body),bytes:body.length,inputSha256:record.sha256,entries:record.entries.length};
}

/** A failed command is never retried. Attempt only a read-only diagnostic
 * snapshot; if its strict capture fails, retain that unavailability explicitly. */
export function retainFailedBuildInputSnapshot(directory,before,prefix){
 let after;
 try{after=captureBuildInputs(directory,before.authoredFiles,before.installRoots);}
 catch(error){
  const failure={status:'FAILED_BUILD_INPUT_SNAPSHOT_UNAVAILABLE',name:error.name,messageSha256:hash(String(error.message))};
  writeFileSync(prefix+'-capture-failure-private.json',JSON.stringify(failure)+'\n',{flag:'wx',mode:0o600});return failure;
 }
 const inventory=writePrivateInputInventory(prefix+'-inputs-private.json',after),difference=summarizeInputDifference(before,after);
 writeFileSync(prefix+'-difference-private.json',JSON.stringify(difference)+'\n',{flag:'wx',mode:0o600});
 return {status:'FAILED_BUILD_INPUT_SNAPSHOT_ONLY_NOT_QUALIFIED',inventory,difference};
}

function metadataBody(root,entry){
 assert(entry.type==='file'&&entry.mode===0o600&&entry.bytes>0&&entry.bytes<=4096,'DERIVED_NITRO_METADATA_FILE');
 const path=join(root,METADATA),fd=openSync(path,constants.O_RDONLY|constants.O_NOFOLLOW|constants.O_NONBLOCK);
 try{
  const initial=fstatSync(fd),stamp=s=>[s.dev,s.ino,s.mode,s.uid,s.size,s.mtimeMs,s.ctimeMs];
  assert(initial.isFile()&&initial.size===entry.bytes,'DERIVED_NITRO_METADATA_HANDLE');
  const buffer=Buffer.alloc(4097),count=readSync(fd,buffer,0,buffer.length,0),body=buffer.subarray(0,count);
  assert.equal(count,entry.bytes,'DERIVED_NITRO_METADATA_SIZE');assert.equal(hash(body),entry.sha256,'DERIVED_NITRO_METADATA_CHANGED');
  assert.deepEqual(stamp(fstatSync(fd)),stamp(initial),'DERIVED_NITRO_METADATA_CHANGED');
  assert.deepEqual(stamp(lstatSync(path)),stamp(initial),'DERIVED_NITRO_METADATA_REPLACED');
  const value=JSON.parse(body);assert(value&&Object.getPrototypeOf(value)===Object.prototype,'DERIVED_NITRO_METADATA_OBJECT');
  assert.deepEqual(Object.keys(value),['outputDir'],'DERIVED_NITRO_METADATA_FIELDS');
  assert(typeof value.outputDir==='string'&&value.outputDir.length<=512&&!isAbsolute(value.outputDir)&&!/[\\\0]/.test(value.outputDir),'DERIVED_NITRO_METADATA_PATH');
  // Nitro resolves this relative to the metadata FILE, rather than its dirname.
  const target=resolve(path,value.outputDir),base=join(root,APP,'.eve/builds');
  const selected=relative(base,target).split('/');
  assert(selected.length===2&&/^[a-z0-9][a-z0-9-]{0,127}$/.test(selected[0])&&selected[1]==='output','DERIVED_NITRO_METADATA_TARGET');
  assert.equal(value.outputDir,relative(path,target),'DERIVED_NITRO_METADATA_CANONICAL_RELATIVE');
  // Eve publishes the staged output, then removes its whole generation. Nitro
  // keeps the old staging path. This metadata never identifies runtime output.
  const published=join(root,APP,'.output'),uid=lstatSync(root).uid;
  for(const directory of [join(root,APP,'.eve'),base,published]){
   const observed=lstatSync(directory);
   assert(observed.isDirectory()&&!observed.isSymbolicLink()&&observed.uid===uid,'DERIVED_NITRO_CANONICAL_DIRECTORY');
   assert.equal(realpathSync(directory),directory,'DERIVED_NITRO_DIRECTORY_ALIAS');
  }
  let removed=false;
  try{lstatSync(join(base,selected[0]));}
  catch(error){if(error.code!=='ENOENT')throw error;removed=true;}
  assert(removed,'DERIVED_NITRO_STAGING_GENERATION_STILL_PRESENT');
  return {path:METADATA,sha256:entry.sha256,target:relative(root,target),
   semantics:'INACTIVE_REMOVED_STAGING_REFERENCE_NOT_RUNTIME_OUTPUT_AUTHORITY',
   scratchGenerationState:'ABSENT_AFTER_SUCCESSFUL_OWNED_BUILD',publishedOutput:relative(root,published),
   publishedOutputValidation:'CANONICAL_DIRECTORY_ONLY_INDEPENDENT_OUTPUT_SEAL_AND_RUNTIME_PROOF_REQUIRED',
   publicationRenameEvent:'NOT_OBSERVED_BY_THIS_VALIDATOR'};
 }finally{closeSync(fd);}
}

export function validateEveDerivedInputTransition(directory,before,after,command,node){
 const original=validateRecord(before),current=validateRecord(after);assertEveDerivedInputsAbsent(before);
 const root=resolve(directory);assert.equal(realpathSync(root),root,'DERIVED_INPUT_CANONICAL_ROOT');
 assert.equal(before.root.path,root,'DERIVED_INPUT_ROOT');
 for(const key of ['format','status','root','authoredFiles','installRoots','generatedBoundaries'])
  assert.equal(hash(JSON.stringify(after[key])),hash(JSON.stringify(before[key])),'DERIVED_INPUT_BOUNDARY_CHANGED:'+key);
 assert(command&&command.binary===node&&isAbsolute(node)&&command.cwd===join(root,APP),'DERIVED_INPUT_BUILD_COMMAND');
 assert.deepEqual(command.args,[join(root,'node_modules/eve/bin/eve.js'),'build'],'DERIVED_INPUT_BUILD_COMMAND');
 assert(Number.isInteger(command.pid)&&command.pid>0&&command.processGroupId===command.pid&&command.exitCode===0
  &&command.groupQuiescent===true&&command.cleanupScope==='OWN_PROCESS_GROUP_ONLY','DERIVED_INPUT_BUILD_OWNERSHIP');
 assert(typeof command.logSha256==='string'&&/^[a-f0-9]{64}$/.test(command.logSha256),'DERIVED_INPUT_BUILD_LOG');
 const diff=summarizeInputDifference(before,after);
 if(diff.removed||diff.changed)throw Object.assign(Error('DERIVED_ORIGINAL_INPUT_CHANGED'),{inputDiff:diff});
 const added=after.entries.filter(entry=>!original.has(entry.path));
 assert(added.length>0&&added.length<=4096,'DERIVED_INPUT_ENTRY_BOUND');
 const directories=new Set([CACHE,EVE,MODULES,NITRO]);let moduleCount=0,totalBytes=0;
 for(const entry of added){
  assert.equal(lstatSync(join(root,entry.path)).uid,before.root.uid,'DERIVED_INPUT_OWNER');
  if(directories.has(entry.path))assert(entry.type==='directory'&&entry.mode===0o700,'DERIVED_INPUT_DIRECTORY');
  else{
   assert(entry.type==='file'&&entry.mode===0o600,'DERIVED_INPUT_REGULAR_PRIVATE_FILE');
   assert(entry.path===METADATA||(entry.path.startsWith(MODULES+'/')&&/^[a-f0-9]{40}\.mjs$/.test(entry.path.slice(MODULES.length+1))),'DERIVED_INPUT_UNDECLARED_ADDITION');
   assert(entry.bytes>0&&entry.bytes<=16*1024**2,'DERIVED_INPUT_FILE_BOUND');
   assert.match(entry.sha256,/^[a-f0-9]{64}$/,'DERIVED_INPUT_BODY');
   totalBytes+=entry.bytes;if(entry.path!==METADATA)moduleCount++;
  }
 }
 assert(moduleCount>0&&totalBytes<=MAX_DERIVED_BYTES,'DERIVED_INPUT_BYTE_BOUND');
 for(const path of [EVE,MODULES,NITRO,METADATA])assert(current.has(path)&&!original.has(path),'DERIVED_INPUT_REQUIRED_ADDITION');
 assert.equal(after.totalBytes-before.totalBytes,totalBytes,'DERIVED_INPUT_TOTAL_BYTES');
 const metadata=metadataBody(root,current.get(METADATA));
 const payload={format:'myapps.eve-derived-input-transition.v1',status:'DERIVED_BUILD_BYTES_CAPTURED_NOT_QUALIFIED',
  beforeSha256:before.sha256,afterSha256:after.sha256,stage:'AFTER_OWNED_PUBLIC_EVE_BUILD',command,
  entries:added,totalBytes,moduleCount,metadata,originalEntriesPreserved:original.size,
  limits:'Generated authored JavaScript and metadata are derived executable/data bytes, not authenticated published package files. All later full-input/runtime/closure checks remain mandatory.'};
 return {...payload,sha256:hash(JSON.stringify(payload))};
}
